{"implementation":"def solve(case):
    payload = case
    nodes = payload['nodes']
    core = payload['core_distance']
    distances = payload['distances']
    for node in nodes:
        if node not in core:
            raise ValueError(f"Missing core distance for {node}")
    edges = []
    for u, v, d in distances:
        if u not in core or v not in core:
            raise ValueError(f"Unknown node in distance: {u} or {v}")
        m = max(core[u], core[v], d)
        if u > v:
            u, v = v, u
        edges.append((m, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append({"source": u, "target": v, "weight": w})
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Input graph is disconnected")
    return {"edges": mst_edges, "total_weight": total_weight}"}
